import{_ as t,o as a,c as s,a2 as n}from"./chunks/framework.BWuWLRhz.js";const p=JSON.parse('{"title":"Startup Panel","description":"","frontmatter":{},"headers":[],"relativePath":"user-guide/settings/startup-panel.md","filePath":"user-guide/settings/startup-panel.md","lastUpdated":1783481530000}'),i={name:"user-guide/settings/startup-panel.md"};function o(r,e,l,d,h,u){return a(),s("div",null,[...e[0]||(e[0]=[n('<h1 id="startup-panel" tabindex="-1">Startup Panel <a class="header-anchor" href="#startup-panel" aria-label="Permalink to &quot;Startup Panel&quot;">​</a></h1><p>A tab strip shown above the result list in the quick window whenever the search box is empty, giving quick access to recent files, favorites, and history without typing a query.</p><ul><li><strong>Enable the startup panel</strong> — master switch; off means the panel never activates at all, regardless of the per-tab settings below.</li></ul><p>Two sub-tabs: <strong>Recent Files</strong> and <strong>Plugin Tabs</strong>.</p><h2 id="recent-files" tabindex="-1">Recent Files <a class="header-anchor" href="#recent-files" aria-label="Permalink to &quot;Recent Files&quot;">​</a></h2><ul><li><strong>Enable panel</strong> — checkbox; shows the tab when the search box is empty.</li><li><strong>Directories</strong> — folders to watch, one per line (same add/edit/remove-row and bulk-text editing as <a href="./index-drives.html#exclusion-rules">Exclusion Rules</a>). Can include local drives, mapped network drives, and WSL paths (<code>\\\\wsl$\\...</code> or <code>\\\\wsl.localhost\\...</code>) — matched against whichever of those you&#39;ve already configured and indexed under <a href="./index-drives.html">Index</a>.</li><li><strong>Maximum number of files to show</strong> — range 1–100, default 10.</li><li><strong>Time range (minutes)</strong> — only files modified within this many minutes of now are eligible, on top of the count cap above. Range 1–43200 (30 days), default 60.</li></ul><h2 id="plugin-tabs" tabindex="-1">Plugin Tabs <a class="header-anchor" href="#plugin-tabs" aria-label="Permalink to &quot;Plugin Tabs&quot;">​</a></h2><p>Plugin-provided tabs (e.g. History, Favorites) each show a <strong>×</strong> button in the live panel to hide them for now. This is a panel-local &quot;hide it&quot; choice — separate from disabling the plugin component itself in <a href="./plugins.html">Plugins</a>, which stops it from being used at all. A tab closed this way is listed here, grouped by the plugin that provides it, unchecked; check it to bring it back.</p><p>Only tabs whose plugin component is currently enabled show up in this list — one disabled entirely under <a href="./plugins.html">Plugins</a> never becomes a tab candidate in the first place.</p>',9)])])}const g=t(i,[["render",o]]);export{p as __pageData,g as default};
